 14	    private static SearchResult search(int[] values, int target) {
 15	        SearchRange range = new SearchRange(values.length);
 16	
 17	        while (range.hasValues()) {
 18	            int mid = range.midpoint();
 19	            int midValue = values[mid];
 20	
 21	            if (isMatch(midValue, target)) {
 22	                return SearchResult.foundAt(mid);
 23	            }
 24	
 25	            if (isBelowTarget(midValue, target)) {
 26	                range.discardLeftThrough(mid);
 27	            } else {
 28	                range.discardRightThrough(mid);
 29	            }
 30	        }
 31	
 32	        return SearchResult.notFound();
 33	    }
